INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'Chemistry', 'Unit 2', 'Molarum Grade 10 — Chemistry SOLUTIONS', 'Source-grounded Molarum Grade 10 Chemistry questions for SOLUTIONS.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('782e8edc-b251-40c6-8107-e1cb3ce0ded3'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which of the following describes a homogeneous mixture?', 'A homogeneous mixture has uniform composition throughout (e.g., salt dissolved in water).', 'Homogeneous mixtures have the same composition and properties throughout; an example is a salt in water where the solution is uniform.', 0),('1ffff733-ddbb-4e10-807a-8ffe309e539b'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'In a solution, water is the solvent and salt is the solute. This describes:', 'Water is the solvent and salt is the solute.', 'In a solution, the solvent is the medium in which the solute is dissolved; water commonly serves as the solvent and salt as the solute.', 1),('ec5491ca-6656-4357-8944-f57abc871677'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'What does molarity measure?', 'Moles of solute per liter of solution', 'Molarity is defined as the number of moles of solute per liter of solution (mol/L).', 2),('145de48b-81e6-407c-8da6-d8459c42d5c8'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'If more solute can dissolve at a given temperature, the solution is:', 'unsaturated', 'An unsaturated solution can still dissolve more solute at that temperature.', 3),('2be8e290-d813-44c7-878e-2eff1a566af4'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which statement about concentration units is true?', 'Molarity changes with temperature, while molality remains essentially constant.', 'Molarity depends on volume, which changes with temperature, while molality depends on mass of solvent and is largely temperature independent.', 4),('cd37cc5e-2c05-4b6c-82b2-3feafb1d0443'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'true_false', 'At a fixed temperature, a saturated solution contains the maximum amount of solute that can dissolve.', 'True', 'A saturated solution has dissolved as much solute as possible at that temperature.', 5),('363ce896-1711-452e-8b71-90bf2f5d5389'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Explain, in 1–2 sentences, why increasing temperature generally increases the solubility of most solid solutes in water.', 'Increasing temperature provides more energy to overcome lattice energy and to solvate ions or molecules, which often increases the amount of solid that can dissolve. For many salts, dissolution is endothermic, so solubility rises with temperature.', 'Higher temperature generally increases molecular motion and energy available for dissolution, often shifting equilibrium toward greater solubility for solids (endothermic dissolution for many salts).', 6),('d83e13dd-549e-48a2-8cab-d1ef49f43da3'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Describe the difference between saturated, unsaturated, and supersaturated solutions.', 'Saturated: contains as much solute as can dissolve at a given temperature; unsaturated: can dissolve more solute; supersaturated: contains more solute than normally dissolvable, often created by heating a saturated solution and slowly cooling.', 'Definitions based on how much solute is in solution relative to solubility at a given temperature.', 7),('cb1da9d6-f373-41f7-8b1f-23d02c5b9eb9'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'A student dissolves 24.0 g of NaCl in enough water to make 0.500 L of solution. What is the molarity (mol/L) of the solution? Show all steps and final unit.', '0.822 M', 'Moles NaCl = 24.0 g / 58.44 g/mol = 0.4109 mol; Molarity = 0.4109 mol / 0.500 L = 0.8218 M ≈ 0.822 M.', 8),('4a610ae7-8050-4b34-84aa-b54c1b252731'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'A solution is prepared by dissolving 25.0 g of glucose in 125.0 g of water. Calculate the mass percent (m/m) of glucose in the solution.', '16.7% (m/m)', 'Total mass = 25.0 + 125.0 = 150.0 g; mass percent = (25.0 / 150.0) × 100 = 16.7%.', 9),('bb231989-d766-4937-830e-e70a79d62e59'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'What is molarity?', 'Moles of solute per liter of solution', 'Molarity is defined as the number of moles of solute dissolved per liter of solution.', 10),('d0b341a4-0950-4271-8de9-cd51fc007bc8'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Percent by mass/volume is defined as (mass of solute / volume of solution) × 100. Which statement best describes this concentration expression?', 'Mass of solute per liter of solution × 100', 'Percent by mass/volume expresses how much solute is present per liter of solution, scaled by 100.', 11),('69da15d0-0fbd-44dd-87ce-afb9d6a9e243'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'When an ionic solid dissolves in water, the ions become surrounded by water molecules. This process is called:', 'Hydration (solvation)', 'Dissolution involves interaction with water molecules; ions become solvated, i.e., surrounded by water molecules (hydration/solvation).', 12),('d04cd565-c34f-4786-8459-93b6b5d963e1'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which factor most clearly increases the rate of dissolution of a solid solute in a solvent?', 'Stirring the solution', 'Rate of dissolution increases with greater surface area exposure and stirring, which reduce boundary layers and bring fresh solvent; stirring is a key factor.', 13),('78f36522-4e6c-4d2c-8a45-cb6f69046144'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'If 0.50 moles of solute are dissolved in 1.00 liter of solution, what is the molarity?', '0.50 M', 'Molarity = moles of solute / liters of solution. Here is 0.50 mol in 1.00 L → 0.50 M.', 14),('33b29fca-338b-419b-85ea-0b150061935c'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'How many milliliters of a 1.00 M stock NaCl solution are required to prepare 1.00 L of a 0.100 M NaCl solution? Use the dilution formula M1V1 = M2V2.', '100 mL of 1.00 M stock solution', 'Using M1V1 = M2V2: (1.00 M)(V1) = (0.100 M)(1.00 L) → V1 = 0.100 L = 100 mL.', 15),('9cb71827-1ae9-43af-82f4-e176b7523e9f'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'true_false', 'The molarity of a solution is independent of temperature.', 'False', 'Molarity depends on the volume of solution, which changes with temperature; hence it is temperature-dependent.', 16),('f9f78559-a33a-4ff6-8654-c8de3ab638f2'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Calculate the grams of potassium nitrate (KNO3, molar mass = 101.10 g/mol) required to prepare 1.000 L of a 0.500 M KNO3 solution.', '50.6 g (approximately) of KNO3 to be weighed and dissolved to make 1.000 L of 0.500 M solution.', 'Mass = Molarity × Volume × MolarMass = 0.500 mol/L × 1.000 L × 101.10 g/mol ≈ 50.55 g; rounded to 50.6 g.', 17),('abf8d185-1e25-4255-8da0-41e845f13905'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'In the reaction HCl + NaOH → NaCl + H2O, if 25.0 mL of 1.00 M HCl reacts with 25.0 mL of 1.00 M NaOH, how many grams of NaCl are produced?', '1.46 g of NaCl (approximately; 0.0250 mol NaCl; 0.0250 mol × 58.44 g/mol ≈ 1.46 g)', 'Reaction is 1:1; moles of HCl = moles of NaOH = 0.0250 mol; NaCl produced = 0.0250 mol; mass = 0.0250 × 58.44 ≈ 1.46 g.', 18),('42ac519d-fcaa-48ec-839f-3a3648a4f0f4'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'A school lab needs 0.500 L of a 0.200 M CaCl2 solution. A stock solution of 1.00 M CaCl2 is available. How many milliliters of stock are required? Use M1V1 = M2V2.', '100 mL of 1.00 M CaCl2 stock', 'M1V1 = M2V2 → (1.00 M)(V1) = (0.200 M)(0.500 L) → V1 = 0.100 L = 100 mL', 19),('13921125-3d18-45e1-8786-266e3f27415f'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'A solution contains 5.0 moles of solute dissolved in 2.0 liters of solution. What is the molarity of the solution?', '2.5 M', 'Molarity = moles of solute / liters of solution = 5.0 / 2.0 = 2.5 mol/L (M).', 20),('69127f7d-df14-43ce-8aa7-4aadc0b9eb37'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which concentration expression uses the mass of solvent in kilograms?', 'Molality', 'Molality = moles of solute per kilogram of solvent.', 21),('abbd975e-2e37-4162-8d1a-71a1f1628b80'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which statement best describes an unsaturated solution at a given temperature?', 'Contains less solute than the maximum at that temperature.', 'An unsaturated solution has less solute than the equilibrium maximum at that temperature.', 22),('165d1b51-d8bc-41f9-8067-9ff88ccc741b'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which factor most affects the solubility of a gas in a liquid?', 'Pressure', 'Gas solubility in liquids generally increases with pressure (Henry''s law); temperature also matters but gas solubility typically decreases with higher temperature.', 23),('faa01ddf-0027-48b6-841f-e78aad321931'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'A solution contains 20 g of solute in 100 g of solution. What is the percent by mass of the solute?', '20%', 'Percent by mass = (mass solute / mass of solution) × 100 = (20 g / 100 g) × 100 = 20%.', 24),('d92c325a-6de5-437e-857d-67c2eae9f197'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'true_false', 'Stirring a solute in a solvent always increases the rate at which the solute dissolves.', 'True', 'Stirring increases contact between solute and solvent, increasing the rate of dissolution.', 25),('aa26a320-6c2c-4850-8ae2-2d51361fd008'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Explain how adding more solvent to a solution affects the molarity of the solution, assuming the amount of solute remains the same.', 'Molarity decreases as solvent is added because molarity is moles per liter; increasing volume with constant moles reduces M.', 'Molarity = n/V. If n stays constant and V increases, M decreases.', 26),('ea4d26f0-3748-4c54-8504-f2e72efb238d'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Define saturated, unsaturated, and supersaturated solutions and describe how a supersaturated solution can be prepared.', 'Saturated: solute at equilibrium with undissolved solute; Unsaturated: can dissolve more solute at that temperature; Supersaturated: holds more solute than the equilibrium limit, created by dissolving at high temperature and slowly cooling; preparation: dissolve at high T, then cool slowly without disturbance.', 'Supersaturation is achieved by manipulating temperature and careful handling to avoid nucleation.', 27),('aabbedd0-c170-40e6-8a5a-3850e0cd0c15'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'A solution contains 0.500 moles of solute in 2.00 liters of solution. What is its molarity? Show your calculation.', '0.250 M', 'Molarity M = n/V = 0.500 mol / 2.00 L = 0.250 mol/L (M).', 28),('41e691dc-8df6-4b15-85f5-d707ea4d8830'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'A stock solution of concentration 3.00 M is used to prepare 0.600 mol of solute in a final solution with a concentration of 0.750 M. What final volume is required?', '0.800 L', 'Using C1V1 = C2V2; n = C2V2 = 0.600 mol; V2 = n/C2 = 0.600 mol / 0.750 mol/L = 0.800 L.', 29),('05c80759-53a9-4acc-8830-fbf56c69f822'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which of the following is a homogeneous solution?', 'Sugar dissolved in water', 'A solution is a homogeneous mixture; sugar dissolved in water forms a uniform composition throughout.', 30),('57b8fbd3-cd72-4503-8a0e-e3ce9e15bb20'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'true_false', 'A solution never settles out over time.', 'True', 'Solutions are homogeneous and do not separate by gravity; they remain uniformly mixed over time.', 31),('cf4e0421-3bc8-4a44-8740-0c6dc384d39b'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'In a solution, what is the solvent?', 'Solvent', 'The solvent is the substance in which the solute dissolves and is usually present in the larger amount.', 32),('64b032a2-0c0e-46c6-872d-c5f89c3acd6a'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'Which statement about molarity is correct?', 'Molarity is the number of moles of solute per liter of solution.', 'Molarity (M) is defined as moles of solute per liter of solution (mol/L).', 33),('bcf25a74-7ec9-4308-8cc5-42fcadb48b6f'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'A saturated solution at a given temperature contains:', 'It contains the maximum amount of solute that can dissolve at that temperature.', 'A saturated solution holds the maximum dissolved solute at that temperature; additional solute remains undissolved.', 34),('a943161a-5f7a-440b-815d-5c0ce98a3d37'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'State the formula for molarity and the units it uses.', 'Molarity = moles of solute per liter of solution; units: mol/L (M).', 'Molarity (M) is defined as the amount of solute in moles divided by the volume of solution in liters.', 35),('48863cb0-1ce2-4303-8b2b-95024e70de35'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Name two factors that affect the solubility of a solid in a liquid.', 'Temperature and agitation (stirring) [and/or particle size]', 'Solubility is influenced by temperature; agitation and particle size can affect the rate at which dissolution occurs.', 36),('0f67d9bf-aa00-4207-894e-57cb5d1b7449'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'Calculate the molarity of a solution containing 5.0 moles of solute in 2.0 liters of solution. Provide all values, units, context, and explain the method.', '2.5 M', 'Molarity M = moles of solute / liters of solution; here M = 5.0 mol / 2.0 L = 2.5 mol/L (2.5 M).', 37),('f35df547-d938-464c-857d-61f9d698b65d'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'fill_blank', 'How many grams of NaCl are required to prepare 1.00 L of a 0.500 M NaCl solution? (M NaCl = 58.44 g/mol)', '29.22 g', 'Moles needed = M × V = 0.500 mol/L × 1.00 L = 0.500 mol; mass = 0.500 mol × 58.44 g/mol = 29.22 g.', 38),('0a950fe7-d645-4e09-875a-5ac710fc8013'::uuid, '7ca5dccb-1862-48a0-8a2e-3a712cc0f8dc'::uuid, 'multiple_choice', 'For a saturated solution at a fixed temperature, which statement is true?', 'It contains the maximum amount of solute that can dissolve at that temperature.', 'A saturated solution contains the maximum amount of solute that can dissolve at that temperature; any additional solute remains undissolved.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
